import { FC, useState } from 'react';
import { Accordion } from 'shared/Accordion';
import { StepHeader } from '../StepHeader';
import { FrameColor } from './FrameColor';
import { FrameColorPalette } from './FrameColorPalette';
import { PanelColor } from './PanelColor';
import { PanelColorPalette } from './PanelColorPalette';

/**
 * Added the color builder because tailwind can't generate dynamic classes, just import the name of the class that is dynamic
 * bg-ral-1013 bg-ral-1014 bg-ral-1015 bg-ral-1016 bg-grad-export-1013 bg-grad-export-1014 bg-grad-export-1015 bg-wood-1013 bg-wood-1014 bg-wood-1015
 */

export const ColorsStep: FC = () => {
  const [isOpen, setIsOpen] = useState(true);

  return (
    <div className="px-16 md:px-32 py-20 bg-white" id="colors">
      <StepHeader title="Colors" isOpen={isOpen} setIsOpen={setIsOpen} />
      <Accordion isOpen={isOpen}>
        <PanelColorPalette />
        <PanelColor />
        {/* <PanelTwoColorPalette />
        <PanelTwoColor /> */}
        <FrameColorPalette />
        <FrameColor />
      </Accordion>
    </div>
  );
};

